<body><div class="container"><div class="main-content"><main class="page-content"><div class="page-header"><h1>Email Settings</h1><a class="btn" href="index.php">Back to Dashboard</a></div><div class="content-box"><p>Use a Gmail App Password or your email provider SMTP password. Never use your normal Gmail password.</p><form id="emailForm"><div class="form-row"><div class="form-group"><label for="smtpHost">SMTP Host</label><input id="smtpHost" required value="smtp.gmail.com"></div><div class="form-group"><label for="smtpPort">SMTP Port</label><input id="smtpPort" type="number" required value="587"></div></div><div class="form-row"><div class="form-group"><label for="smtpUsername">Email Username</label><input id="smtpUsername" type="email" required value="visiondatacompany97@gmail.com"></div><div class="form-group"><label for="smtpPassword">App Password</label><input id="smtpPassword" type="password" required></div></div><div class="form-row"><div class="form-group"><label for="smtpEncryption">Encryption</label><select id="smtpEncryption"><option value="tls">TLS</option><option value="ssl">SSL</option></select></div><div class="form-group"><label for="fromName">Sender Name</label><input id="fromName" required value="Happy Cow Animal Feeds"></div></div><div class="form-group"><label for="fromEmail">From Email</label><input id="fromEmail" type="email" required value="visiondatacompany97@gmail.com"></div><label><input type="checkbox" id="enabled"> Enable email</label><label><input type="checkbox" id="sendReceipts" checked> Send receipts</label><label><input type="checkbox" id="sendQuotations" checked> Send quotations</label><p id="message" class="alert" hidden></p><button class="btn btn-primary" type="submit">Save Email Settings</button></form></div></main></div></div><script>const form=document.getElementById('emailForm'),message=document.getElementById('message');fetch('api/get_email_settings.php').then(r=>r.json()).then(d=>{if(d.success){const s=d.settings;for(const [id,key] of [['smtpHost','smtp_host'],['smtpPort','smtp_port'],['smtpUsername','smtp_username'],['smtpPassword','smtp_password'],['smtpEncryption','smtp_encryption'],['fromEmail','from_email'],['fromName','from_name']])if(s[key]!==undefined)document.getElementById(id).value=s[key];for(const [id,key] of [['enabled','enabled'],['sendReceipts','send_receipts'],['sendQuotations','send_quotations']])document.getElementById(id).checked=String(s[key])==='1';}});form.addEventListener('submit',e=>{e.preventDefault();const d={smtp_host:smtpHost.value,smtp_port:smtpPort.value,smtp_username:smtpUsername.value,smtp_password:smtpPassword.value,smtp_encryption:smtpEncryption.value,from_email:fromEmail.value,from_name:fromName.value,enabled:enabled.checked?1:0,send_receipts:sendReceipts.checked?1:0,send_quotations:sendQuotations.checked?1:0};fetch('api/save_email_settings.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)}).then(r=>r.json()).then(d=>{message.hidden=false;message.textContent=d.message;message.className='alert alert-'+(d.success?'success':'error');});});</script></body></html>
